{
  "name": "Odin探测器数据写出节点",
  "name_en": "Odin detector data writer node",
  "manufacturer": "",
  "description": "Odin探测器数据写出节点是与高速科学探测器配套的数据采集与存储单元，用于在实验过程中接收连续曝光产生的帧数据，按采集顺序写出并跟踪已写入索引，便于后续流式处理与分析。",
  "description_en": "An Odin detector data writer node is a data acquisition and storage unit used with high-speed scientific detectors. During experiments it receives frame data from successive exposures, writes them in acquisition order, and tracks written indices for downstream streaming and analysis.",
  "tag_hints": [
    "detector data acquisition",
    "data writer node",
    "high-rate detector readout",
    "frame index tracking",
    "streaming experiment data",
    "Odin data system"
  ],
  "actions": [
    {
      "action_name": "auto-open",
      "description": "打开一次探测器数据写出会话，并设置每个事件对应的曝光数。",
      "description_en": "Open a detector data writing session and set the number of exposures per event."
    },
    {
      "action_name": "auto-observe_indices_written",
      "description": "监视已写入的数据索引变化，直到超时或检测到新写入。",
      "description_en": "Observe changes in the written data indices until timeout or until new data are written."
    },
    {
      "action_name": "auto-collect_stream_docs",
      "description": "收集与已写入索引对应的数据流文档，用于后续数据处理。",
      "description_en": "Collect stream documents corresponding to the written indices for downstream data processing."
    },
    {
      "action_name": "auto-close",
      "description": "关闭当前数据写出会话。",
      "description_en": "Close the current data writing session."
    },
    {
      "action_name": "auto-get_indices_written",
      "description": "获取已写入的数据索引数。",
      "description_en": "Get the number of data indices written."
    }
  ]
}

